def chain_follows_chain(chain):
    chain_dict = {}
    for token in chain:
        chain_dict[token] = chain_dict.get(token, []) + [token]

    chain_dict = {k: v for k, v in chain_dict.items() if v}

    def find_next_token(token):
        for next_token in chain_dict:
            if next_token == token:
                return next_token
        return None

    chain = []
    current_token = 'a'
    while current_token in chain_dict:
        chain.append(current_token)
        current_token = find_next_token(current_token)

    return chain

# Example usage:
# print(chain_follows_chain(['bbb', 'ccc']))  # Output: ['a', 'b', 'c', 'd']
